import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"Executive summary","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/EXECUTIVE-SUMMARY.html"}],["meta",{"property":"og:title","content":"Executive summary | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/EXECUTIVE-SUMMARY.html"}],["meta",{"name":"twitter:title","content":"Executive summary | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/EXECUTIVE-SUMMARY.md","filePath":"audits/EXECUTIVE-SUMMARY.md","lastUpdated":1794184492000}`),a={name:`audits/EXECUTIVE-SUMMARY.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to “Executive summary”">​</a></h1><p><strong>Source:</strong> <code>dev</code> at <code>a455462a959f37db757970d0a3078a4d9a3ef028</code><br><strong>Review type:</strong> Static engineering audit against the project <a href="https://github.com/aaron-fredrick/RULESETS" target="_blank" rel="noreferrer">RULESETS</a>.<br><strong>Owner feedback:</strong> Incorporated into the <a href="./IMPLEMENTATION-PLAN.html">implementation plan</a>.</p><h2 id="overall-assessment" tabindex="-1">Overall assessment <a class="header-anchor" href="#overall-assessment" aria-label="Permalink to “Overall assessment”">​</a></h2><p>FD Cal has a solid foundation: the browser and CLI share the JavaScript engine; the browser calculation runs in a dedicated worker; the configuration shape is explicitly validated; reporting escapes most dynamic text; the standalone report is self-contained; search diagnostics expose pruning and optimality status; and the test suite includes financial, strategy-parity, worker-contract, reporting and workflow-contract coverage.</p><p>The main risks are not a lack of architecture. They are a small number of important trust-boundary, financial-presentation, runtime, and catalogue-transparency gaps:</p><ol><li>Imported account IDs can reach HTML attributes without escaping, creating a DOM-XSS path.</li><li>The displayed “Final value” is a pre-withdrawal capital-plus-return measure, not the actual closing portfolio value after paid outflows.</li><li>Installment products can generate a final payment date after nominal FD maturity; contractual payout semantics need confirmation before changing this.</li><li>Product-source quality and dataset freshness are not sufficiently visible in the user-facing product selection/report.</li><li>The browser&#39;s default Absolute R+ run has no default decision cap or post-start execution timeout.</li></ol><p>The project should not be described as financially validated until output semantics, payout timing, day-count conventions, and product-source transparency have been explicitly documented and tested.</p><h2 id="priority-findings" tabindex="-1">Priority findings <a class="header-anchor" href="#priority-findings" aria-label="Permalink to “Priority findings”">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Finding</th><th>Main location</th></tr></thead><tbody><tr><td>SEC-01</td><td><strong>P1</strong></td><td>Unescaped imported account IDs are interpolated into account-card HTML attributes</td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js" target="_blank" rel="noreferrer">app.js</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/config-schema.js" target="_blank" rel="noreferrer">config-schema.js</a></td></tr><tr><td>FIN-01</td><td><strong>P1</strong></td><td>“Final value” is a pre-withdrawal aggregate but is presented as closing portfolio value</td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/results.js" target="_blank" rel="noreferrer">results.js</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js" target="_blank" rel="noreferrer">app.js</a></td></tr><tr><td>ENG-01</td><td><strong>P2</strong></td><td>Installment cash-flow generation can place the final payment after nominal maturity; product contract needs clarification</td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/models.js" target="_blank" rel="noreferrer">models.js</a></td></tr><tr><td>ENG-02</td><td><strong>P2</strong></td><td>Actual elapsed days use one 365/366 base selected from the accrual start year</td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/interest.js" target="_blank" rel="noreferrer">interest.js</a></td></tr><tr><td>SEARCH-01</td><td><strong>P2</strong></td><td>Scoped Absolute R+ has no finite default decision cap or post-start time limit</td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/strategies/search-strategy-base.js" target="_blank" rel="noreferrer">search-strategy-base.js</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/simulation-runner.js" target="_blank" rel="noreferrer">simulation-runner.js</a></td></tr><tr><td>DATA-01</td><td><strong>P2</strong></td><td>Per-bank source status and dataset freshness are not adequately exposed to users</td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js" target="_blank" rel="noreferrer">app.js</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/data/fd_options/fd_options.csv" target="_blank" rel="noreferrer">fd_options.csv</a></td></tr><tr><td>DATA-02</td><td><strong>Scope boundary</strong></td><td>Senior/minor toggles include product categories; they do not verify depositor eligibility</td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/configuration.js" target="_blank" rel="noreferrer">configuration.js</a></td></tr><tr><td>DATA-03</td><td><strong>Deferred</strong></td><td>Active FD model does not represent all special-product caps/tax treatment in the research register</td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/models.js" target="_blank" rel="noreferrer">models.js</a></td></tr><tr><td>DEPLOY-01</td><td><strong>P2</strong></td><td>Production Pages assembly must preserve the public <code>/dev/</code> subtree on every deployment</td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/.github/workflows/pages.yml" target="_blank" rel="noreferrer">pages.yml</a></td></tr><tr><td>DATA-04</td><td><strong>P3</strong></td><td>CSV parser silently ignores surplus fields and fills missing fields with empty strings</td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/io/csv.js" target="_blank" rel="noreferrer">csv.js</a></td></tr><tr><td>UI-01</td><td><strong>P3</strong></td><td>Programmatic smooth scrolling does not check reduced-motion preference</td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js" target="_blank" rel="noreferrer">app.js</a></td></tr><tr><td>QA-01</td><td><strong>Deferred</strong></td><td>No automated real-browser end-to-end suite was identified in the test inventory</td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/tree/a455462a959f37db757970d0a3078a4d9a3ef028/tests" target="_blank" rel="noreferrer">tests/</a></td></tr></tbody></table><h2 id="owner-feedback-and-decisions" tabindex="-1">Owner feedback and decisions <a class="header-anchor" href="#owner-feedback-and-decisions" aria-label="Permalink to “Owner feedback and decisions”">​</a></h2><table tabindex="0"><thead><tr><th>Finding</th><th>Decision / interpretation</th><th>Planned treatment</th></tr></thead><tbody><tr><td><strong>SEC-01</strong></td><td>Confirmed valid finding</td><td>P1 security fix. Encode account IDs at the DOM boundary; preserve imported ID compatibility and test malicious files.</td></tr><tr><td><strong>FIN-01</strong></td><td>Confirmed overlooked result-presentation issue</td><td>P1 financial-result correction. The runtime already credits inflows/cash flows, settles outflows, then requests a strategy decision. Search state and terminal evaluation already account for paid and outstanding outflows. Keep settlement in the runtime and strategy objective unchanged; expose separate pre-withdrawal and closing-position metrics.</td></tr><tr><td><strong>ENG-01</strong></td><td>Event order is intentional: cash inflows/FD cash flows first, outflows second, decision third</td><td>Preserve and test this order. It does not alone determine whether a final installment after nominal maturity matches a bank contract. Do not clamp dates until representative product terms establish the correct model.</td></tr><tr><td><strong>ENG-02</strong></td><td>Project intends an actual elapsed-day/relative-delta basis</td><td>Keep the current formula for now; document the exact start-year 365/366 denominator and verify against representative bank terms before changing financial calculations.</td></tr><tr><td><strong>SEARCH-01</strong></td><td>Finite defaults are required, but users may opt into unlimited work</td><td>Benchmark candidate defaults (initial candidates: 10,000 expanded states and 30 seconds); represent unlimited decisions explicitly and use timeout <code>0</code> for unlimited time. Preserve best-feasible-result and optimality diagnostics.</td></tr><tr><td><strong>DATA-01</strong></td><td>Show when each bank&#39;s dataset was last updated/reviewed and add a disclaimer</td><td>Add a bank-specific review date and source status beside the selected bank. Keep this distinct from the bank&#39;s product effective date.</td></tr><tr><td><strong>DATA-02</strong></td><td>Eligibility verification is the user&#39;s responsibility; FD Cal is not a bank onboarding/security gate</td><td>Treat senior/minor toggles as inclusion filters. Retain a clear disclaimer; do not add age/guardian verification as part of this work.</td></tr><tr><td><strong>DATA-03</strong></td><td>Scope not yet clear</td><td>Defer until the owner specifies which special-product constraints should be modelled. Keep products with unenforced critical terms out of the active catalogue.</td></tr><tr><td><strong>DEPLOY-01</strong></td><td>Dev preview is intentionally public for users and contributors</td><td>Make <code>main</code> Pages assembly preserve the latest <code>/dev/</code> subtree; a normal production deploy must not remove it.</td></tr><tr><td><strong>DATA-04</strong></td><td>Needs investigation and a safe implementation plan</td><td>Inventory all CSV files first, then enforce exact row widths and valid quoting with actionable errors.</td></tr><tr><td><strong>UI-01</strong></td><td>Include in the implementation plan</td><td>Centralize programmatic scrolling and honor <code>prefers-reduced-motion</code> without changing normal-motion transitions.</td></tr><tr><td><strong>QA-01</strong></td><td>Needs owner decision</td><td>Finding means no automated real-browser E2E suite was found. Defer the choice between Playwright smoke coverage and manual browser verification.</td></tr></tbody></table><h2 id="positive-controls-worth-preserving" tabindex="-1">Positive controls worth preserving <a class="header-anchor" href="#positive-controls-worth-preserving" aria-label="Permalink to “Positive controls worth preserving”">​</a></h2><ul><li><strong>Shared engine:</strong> the browser worker and CLI call the same core strategy/simulation implementation.</li><li><strong>Runtime boundary:</strong> <code>SimulationRuntime</code> is the authoritative event processor and executor; strategies consume planning views and submit decisions.</li><li><strong>Outflow sequencing:</strong> same-date inflows, FD cash flows, and maturities are credited before outflows are settled; strategy decisions follow settlement.</li><li><strong>Input validation:</strong> configuration keys, data types, ranges and schedule relationships are checked before simulation.</li><li><strong>Worker protocol:</strong> the implementation correctly avoids using <code>event.origin</code> as authentication for a dedicated Worker and validates the message contract.</li><li><strong>Report output:</strong> dynamic report text is generally escaped; embedded JSON protects closing-script sequences; the report is self-contained.</li><li><strong>Strategy transparency:</strong> Absolute R+ exposes expanded states, beam pruning, budgets and optimality status.</li><li><strong>Regression base:</strong> tests include engine, cash-flow, configuration, provenance, strategy parity, worker, report and Pages workflow contracts.</li><li><strong>Privacy posture:</strong> no third-party analytics or session-replay instrumentation was identified in the reviewed application code; the UI says drafts remain in the browser.</li></ul><h2 id="recommended-implementation-order" tabindex="-1">Recommended implementation order <a class="header-anchor" href="#recommended-implementation-order" aria-label="Permalink to “Recommended implementation order”">​</a></h2><ol><li><strong>SEC-01:</strong> close the imported account-ID DOM injection path and add adversarial import regression tests.</li><li><strong>FIN-01:</strong> separate pre-withdrawal aggregate value from closing assets/liabilities/net worth without changing strategy scoring or outflow settlement.</li><li><strong>ENG-01/ENG-02:</strong> document and verify payout/date conventions before any financial formula or cash-flow change.</li><li><strong>SEARCH-01:</strong> introduce bounded defaults, explicit unlimited controls, cooperative timeout, worker safety timeout, cancellation, and benchmark validation.</li><li><strong>DATA-01:</strong> add per-bank dataset review dates and clear source-quality disclosure.</li><li><strong>DEPLOY-01:</strong> make main deployment preserve the public dev preview.</li><li><strong>DATA-04:</strong> harden CSV parsing after the full data inventory.</li><li><strong>UI-01:</strong> add reduced-motion-aware scrolling.</li></ol><p>DATA-02 is an accepted product-scope boundary. DATA-03 and QA-01 remain deferred for owner decisions. Detailed phases, regression cases, and non-regression gates are in <a href="./IMPLEMENTATION-PLAN.html">IMPLEMENTATION-PLAN.md</a>.</p><h2 id="release-and-verification-caveats" tabindex="-1">Release and verification caveats <a class="header-anchor" href="#release-and-verification-caveats" aria-label="Permalink to “Release and verification caveats”">​</a></h2><ul><li>The source audit is not formal financial verification, a penetration test, or bank-product certification.</li><li>The Node test workflow passed on the audited source revision, but that does not prove rendered browser behaviour or financial-product correctness.</li><li>No manual browser, screen-reader, or full WCAG assessment was completed as part of the static audit.</li><li>The dev preview is a subtree of the same GitHub Pages site. Production and dev deployments must be serialized and both must preserve the other&#39;s published files.</li><li>No application implementation has been applied on this audit branch; it remains a report and planning branch.</li></ul>`,18)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};